  str_senior_skin_draw_desc = "스페셜 코스튬 [아쿠아리움 투어]가 6번째 소원부터 보상 목록에 포함되며, 5번째 소원까지는 이를 획득할 수 없습니다.",
  str_senior_skin_draw_draw_gl_btn = "소원 빌기",
