  str_senior_skin_draw_lobby_enter_titleplm = "흐드러진 피라칸타",
  str_senior_skin_draw_rule_title_kr = "인 더 스포트라이트 규칙 설명",
  str_senior_skin_draw_rule_detail_kr = "○ 소원을 빌면 <color=#d70500>1</color>개의 보상을 반드시 획득할 수 있습니다. 첫 소원에는 영화 티켓을 소모하지 않으며, 이후 <color=#d70500>9</color>번의 소원은 영화 티켓을 소모해야 합니다.\n○ 이벤트 보상은 총 <color=#d70500>10</color>개가 존재하며, 각 보상은 <color=#d70500>1</color>회만 획득할 수 있습니다. 소원에서 특정 보상을 획득할 때마다 전체 보상에서 제거되며, 이후 소원 진행 시의 보상에 포함되지 않습니다. <color=#d70500>10</color>회 진행 시 모든 보상을 획득할 수 있습니다.\n○소원 횟수에 따라 소모되는 영화 티켓의 개수가 증가하며, <color=#d70500>2</color>번째에서 <color=#d70500>10</color>번째까지 각각 소모하는 영화 티켓은 <color=#d70500>1</color> / <color=#d70500>1</color> / <color=#d70500>2</color> / <color=#d70500>4</color> / <color=#d70500>6</color> / <color=#d70500>6</color> / <color=#d70500>10</color> / <color=#d70500>10</color> / <color=#d70500>10</color>개입니다. 구체적인 소모 정보는 소원 진행 시 버튼에 표시되므로 유의해 주시기 바랍니다.\n○ 영화 티켓은 유료로 구매할 수 있습니다. 영화 티켓은 기간 한정 아이템으로, <color=#f3bd3c>인 더 스포트라이트</color> 이벤트가 종료되면 사용하지 않은 영화 티켓은 자동으로 <color=#d70500>100</color> 루맘버로 전환되며, 이벤트 종료 <color=#d70500>1</color>시간 후 우편으로 지급됩니다.",
  str_senior_skin_draw_rule_reward_detail_kr = "스페셜 코스튬 <color=#f3bd3c>[천생의 배우]</color>는 <color=#d70500>6</color>번째 소원부터 일정 확률로 획득할 수 있으며, <color=#d70500>10</color>회의 소원을 모두 진행하면 스페셜 코스튬 및 모든 아이템을 획득할 수 있습니다.\n\n전체 보상 내용은 다음과 같습니다.\n최고 보상: 카론 스페셜 코스튬 <color=#f3bd3c>[천생의 배우]</color>*1, 중복 획득 시 루맘버*3000으로 변경\n희귀 보상: 루맘버*<color=#d70500>600</color> + 한정 헤븐즈 가든 건물 <color=#f3bd3c>[윈델리온 가로등]</color>*1, 중복 획득 시 루맘버*600+특별 소집 스타 마커*1로 변경\n희귀 보상: 루맘버*<color=#d70500>600</color> + 한정 프레임 <color=#f3bd3c>[박쥐 헤어밴드]</color>*1, 중복 획득 시 루맘버*600+특별 소집 스타 마커*1로 변경\n희귀 보상: 루맘버*<color=#d70500>600</color> + 한정 아바타 <color=#f3bd3c>[천재 배우 카론]</color>*1, 중복 획득 시 루맘버*600+특별 소집 스타 마커*1로 변경\n고급 보상: 루맘버*<color=#d70500>300</color> + <color=#f3bd3c>빨간색 특급 주문상자</color>*10\n고급 보상: 루맘버*<color=#d70500>300</color> + <color=#f3bd3c>3급 옥 주문상자</color>*25\n고급 보상: 루맘버*<color=#d70500>300</color> + <color=#f3bd3c>충전 상자</color>*10\n중급 보상: 루맘버*<color=#d70500>200</color> + <color=#f3bd3c>2급 옥 주문상자</color>*30\n중급 보상: 루맘버*<color=#d70500>200</color> + <color=#f3bd3c>영질</color>*1000\n중급 보상: 루맘버*<color=#d70500>200</color> + <color=#f3bd3c>나이티움</color>*200000",
  str_senior_skin_draw_rule_reward_tips_title_kr = "확률 설명",
  str_senior_skin_draw_rule_reward_tips_kr = "다음은 본 소원 내 보상 <color=#d70500>10</color>종의 기본 획득 확률입니다.\n특정 보상을 획득하게 되면 나머지 보상의 확률이 동적으로 변화하며, 각 보상의 기본 획득 확률 비율이 재분배됩니다. (총 확률은 여전히 <color=#d70500>100%</color>) <b><color=#302f2f>모든 조종사님께서 이벤트에 참가해 보상을 획득할 기본 확률은 동일합니다.</color></b> <b><color=#f3bd3c>구체적인 동적 확률은 이벤트 메인 화면의 확률 변화 표시 버튼을 참고해 주시기 바랍니다.</color></b>",
  str_senior_skin_draw_dp_title_kr = "인 더 스포트라이트 동적 확률 설명",
  str_senior_skin_draw_rule_probability_detail_kr = "모든 조종사님께서 이벤트에 참가해 보상을 획득할 기본 확률은 동일하며, 자세한 사항은 규칙 설명을 확인해 주시기 바랍니다. 각 보상은 1회만 획득할 수 있으며, 나머지 보상의 획득 확률은 직전 소원 결과에 따라 다시 계산됩니다. <b><color=#302f2f>확률 변화의 원칙은 다음과 같습니다. 이미 획득한 보상을 차감한 후, 소원 횟수와 기본 획득 확률에 따라 나머지 보상의 확률을 동일한 비율로 재분배하며, 확률의 합은 여전히 1이 됩니다.</color></b>",
  str_senior_skin_draw_rule_probability_tips_kr = "<b><color=#f3bd3c>이번 소원은 동적 확률이 적용됩니다. 다음 소원의 확률: </color></b>",
  str_senior_skin_draw_rule_probability_down_kr = "동적 확률은 조종사님마다 차이가 발생할 수 있습니다. 즉, 만약 첫 번째 소원에서 A 님과 B 님이 획득한 보상이 동일하다면, 두 번째 소원에서 나머지 보상의 동적 확률은 동일합니다. 그러나 A 님과 C 님이 첫 번째 소원에서 서로 다른 보상을 획득했다면, 두 번째 소원에서 A 님과 C 님이 서로 다른 보상을 받을 수 있고, 동적 확률도 다릅니다. 문의사항이 있을 경우 고객센터로 연락해 주시기 바랍니다.",
  str_senior_skin_draw_rule_probability_5_times_kr = "{1}회 진행 후",
