  str_senior_skin_draw_cost_not_enough_blh = "{1} 수량 부족",
  str_senior_skin_draw_quanqiu_shoufa = "전격 출시",
  str_senior_skin_draw_rule_reward_detail_gl_review = "스페셜 코스튬 <color=#e89416>[아쿠아리움 투어]</color>는 <color=#d24956>6</color>번째 소원부터 일정 확률로 획득할 수 있으며, <color=#d24956>10</color>회의 소원을 모두 진행하면 스페셜 코스튬 및 모든 보상을 획득할 수 있습니다.\n\n전체 보상 내용은 다음과 같습니다.\n최고 보상: 그로누 스페셜 코스튬 <color=#e89416>[아쿠아리움 투어]</color>*1, 중복 획득 시 루맘버*3000으로 변경\n희귀 보상: 루맘버*<color=#d24956>600</color> + 한정 헤븐즈 가든 건물 <color=#e89416>[경관 산호]</color>*1, 중복 획득 시 루맘버*600+특별 소집 스타 마커*1로 변경\n희귀 보상: 루맘버*<color=#d24956>600</color> + 한정 프레임 <color=#e89416>[바닷가의 양산]</color>*1, 중복 획득 시 루맘버*600+특별 소집 스타 마커*1로 변경\n희귀 보상: 루맘버*<color=#d24956>600</color> + 한정 아바타 <color=#e89416>[게임하는 그로누]</color>*1, 중복 획득 시 루맘버*600+특별 소집 스타 마커*1로 변경\n고급 보상: 루맘버*<color=#d24956>300</color> + <color=#e89416>노란색 특급 주문상자</color>*10\n고급 보상: 루맘버*<color=#d24956>300</color> + <color=#e89416>3급 옥 주문상자</color>*25\n고급 보상: 루맘버*<color=#d24956>300</color> + <color=#e89416>충전 상자</color>*10\n중급 보상: 루맘버*<color=#d24956>200</color> + <color=#e89416>2급 옥 주문상자</color>*30\n중급 보상: 루맘버*<color=#d24956>200</color> + <color=#e89416>영질</color>*1000\n중급 보상: 루맘버*<color=#d24956>200</color> + <color=#e89416>나이티움</color>*200000",
  str_senior_skin_draw_gift_count_gl = "티켓×{1}",
  str_senior_skin_draw_rule_title_qt = "매혹의 밤 규칙 설명",
  str_senior_skin_draw_rule_detail_qt = "○ 소원을 빌면 <color=#d24956>1</color>개의 보상을 반드시 획득할 수 있습니다. 첫 소원에는 고블렛 와인잔을 소모하지 않으며, 이후 <color=#d24956>9</color>번의 소원은 고블렛 와인잔을 소모해야 합니다.\n○ 이벤트 보상은 총 <color=#d24956>10</color>개가 존재하며, 각 보상은 <color=#d24956>1</color>회만 획득할 수 있습니다. 소원에서 특정 보상을 획득할 때마다 전체 보상에서 제거되며, 이후 소원 진행 시의 보상에 포함되지 않습니다. <color=#d24956>10</color>회 진행 시 모든 보상을 획득할 수 있습니다.\n○소원 횟수에 따라 소모되는 고블렛 와인잔의 개수가 증가하며, <color=#d24956>2</color>번째에서 <color=#d24956>10</color>번째까지 각각 소모하는 고블렛 와인잔은 <color=#d24956>1</color> / <color=#d24956>1</color> / <color=#d24956>2</color> / <color=#d24956>4</color> / <color=#d24956>6</color> / <color=#d24956>6</color> / <color=#d24956>10</color> / <color=#d24956>10</color> / <color=#d24956>10</color>개입니다. 구체적인 소모 정보는 소원 진행 시 버튼에 표시되므로 유의해 주시기 바랍니다.\n○ 고블렛 와인잔은 유료로 구매할 수 있습니다. 고블렛 와인잔은 기간 한정 아이템으로, <color=#e89416>매혹의 밤</color> 이벤트가 종료되면 사용하지 않은 고블렛 와인잔은 자동으로 <color=#d24956>100</color> 루맘버로 전환되며, 이벤트 종료 <color=#d24956>1</color>시간 후 우편으로 지급됩니다.",
  str_senior_skin_draw_rule_reward_detail_qt = "스페셜 코스튬 <color=#e89416>[취중진담]</color>은 <color=#d24956>6</color>번째 소원부터 일정 확률로 획득할 수 있으며, <color=#d24956>10</color>회의 소원을 모두 진행하면 스페셜 코스튬 및 모든 아이템을 획득할 수 있습니다.\n\n전체 보상 내용은 다음과 같습니다.\n최고 보상: 아주르 스페셜 코스튬 <color=#e89416>[취중진담]</color>*1, 중복 획득 시 루맘버*3000으로 변경\n희귀 보상: 루맘버*<color=#d24956>600</color> + 한정 헤븐즈 가든 건물 <color=#e89416>[응접실 소파]</color>*1, 중복 획득 시 루맘버*600+특별 소집 스타 마커*1로 변경\n희귀 보상: 루맘버*<color=#d24956>600</color> + 한정 프레임 <color=#e89416>[「진짜」 안경]</color>*1, 중복 획득 시 루맘버*600+특별 소집 스타 마커*1로 변경\n희귀 보상: 루맘버*<color=#d24956>600</color> + 한정 아바타 <color=#e89416>[아주르의 「사냥감」*]</color>*1, 중복 획득 시 루맘버*600+특별 소집 스타 마커*1로 변경\n고급 보상: 루맘버*<color=#d24956>300</color> + <color=#e89416>파란색 특급 주문상자</color>*10\n고급 보상: 루맘버*<color=#d24956>300</color> + <color=#e89416>3급 옥 주문상자</color>*25\n고급 보상: 루맘버*<color=#d24956>300</color> + <color=#e89416>충전 상자</color>*10\n중급 보상: 루맘버*<color=#d24956>200</color> + <color=#e89416>2급 옥 주문상자</color>*30\n중급 보상: 루맘버*<color=#d24956>200</color> + <color=#e89416>영질</color>*1000\n중급 보상: 루맘버*<color=#d24956>200</color> + <color=#e89416>나이티움</color>*200000",
  str_senior_skin_draw_rule_reward_tips_title_qt = "확률 설명",
  str_senior_skin_draw_rule_reward_tips_qt = "다음은 본 소원 내 보상 <color=#d24956>10</color>종의 기본 획득 확률입니다.\n특정 보상을 획득하게 되면 나머지 보상의 확률이 동적으로 변화하며, 각 보상의 기본 획득 확률 비율이 재분배됩니다. (총 확률은 여전히 <color=#d24956>100%</color>) <b>모든 조종사님께서 이벤트에 참가해 보상을 획득할 기본 확률은 동일합니다.</b><b>구체적인 동적 확률은 이벤트 메인 화면의 확률 변화 표시 버튼을 참고해 주시기 바랍니다.</b>",
  str_senior_skin_draw_dp_title_qt = "매혹의 밤 동적 확률 설명",
  str_senior_skin_draw_rule_probability_detail_qt = "모든 조종사님께서 이벤트에 참가해 보상을 획득할 기본 확률은 동일하며, 자세한 사항은 규칙 설명을 확인해 주시기 바랍니다. 각 보상은 1회만 획득할 수 있으며, 나머지 보상의 획득 확률은 직전 소원 결과에 따라 다시 계산됩니다. <b>확률 변화의 원칙은 다음과 같습니다. 이미 획득한 보상을 차감한 후, 소원 횟수와 기본 획득 확률에 따라 나머지 보상의 확률을 동일한 비율로 재분배하며, 확률의 합은 여전히 1이 됩니다.</b>",
  str_senior_skin_draw_rule_probability_tips_qt = "<b><color=#e89416>이번 소원은 동적 확률이 적용됩니다. 다음 소원의 확률: </color></b>",
  str_senior_skin_draw_rule_probability_down_qt = "동적 확률은 조종사님마다 차이가 발생할 수 있습니다. 즉, 만약 첫 번째 소원에서 A 님과 B 님이 획득한 보상이 동일하다면, 두 번째 소원에서 나머지 보상의 동적 확률은 동일합니다. 그러나 A 님과 C 님이 첫 번째 소원에서 서로 다른 보상을 획득했다면, 두 번째 소원에서 A 님과 C 님이 서로 다른 보상을 받을 수 있고, 동적 확률도 다릅니다. 문의사항이 있을 경우 고객센터로 연락해 주시기 바랍니다.",
  str_senior_skin_draw_rule_probability_5_times_qt = "{1}회 진행 후",
  str_senior_skin_draw_lobby_enter_title_qt = "매혹의 밤",
